edits.sketch:
+DO $$
+DECLARE old_tail text := '...needs_brand_head_assets';
+        new_tail text := '...needs_brand_head_assets, dark_section_audit';
+        n int;
+BEGIN
+  SELECT count(*) INTO n FROM scheduled_tasks
+   WHERE name='claimed-item-timeout' AND pre_query LIKE '%'||old_tail||'%';
+  IF n <> 1 THEN RAISE EXCEPTION 'ABORT: predicate not the shape this was written against (matched %)', n; END IF;
+  SELECT count(*) INTO n FROM scheduled_tasks
+   WHERE name='claimed-item-timeout' AND pre_query LIKE '%dark_section_audit%';
+  IF n <> 0 THEN RAISE EXCEPTION 'ABORT: already applied'; END IF;
+  UPDATE scheduled_tasks SET pre_query = replace(pre_query, old_tail, new_tail) WHERE name='claimed-item-timeout';
+  SELECT count(*) INTO n FROM scheduled_tasks WHERE name='claimed-item-timeout'
+     AND pre_query LIKE '%''needs_brand_head_assets'', ''dark_section_audit''%';
+  IF n <> 1 THEN RAISE EXCEPTION 'ABORT: post-write verification failed (matched %)', n; END IF;
+END $$;

+gated := map[string]string{}
+for _, t := range checks.RegisteredVerifierItemTypes() { gated[t] = "a registered verifier (gate 2)" }
+for t := range noChangeGates { gated[t] = "a noChangeGates entry (gate 1b)" }
+for t, why := range gated { if !excluded[t] { t.Errorf("%q has %s but is NOT excluded", t, why) } }
+for t := range excluded { if _, ok := gated[t]; !ok { t.Errorf("%q is excluded but NO gate can grade it") } }

+var itemTypeShapeRe = regexp.MustCompile(`^[a-z][a-z0-9_]*$`)
+for itemType := range excluded {
+	if !itemTypeShapeRe.MatchString(itemType) {
+		t.Fatalf("the exclusion clause in %s parsed to %q, which is not an item_type. The regex takes the\n"+
+			"FIRST match in the file, so a COMMENT above the real declaration is read instead of it.", ...)
+	}
+}
